const resolveMemberEntityId = async (): Promise<string | undefined> => {
  const globalAppState = getGlobalAppState();
  const fromLogin = globalAppState?.loginData?.entity?.id;

  if (typeof fromLogin === 'string' && fromLogin.trim().length > 0) {
    return fromLogin;
  }

  try {
    const userData = await AsyncStorage.getItem('memberData');
    const fromStorage =
      userData && userData !== 'undefined'
        ? JSON.parse(userData)?.entity?.id
        : undefined;

    if (typeof fromStorage === 'string' && fromStorage.trim().length > 0) {
      return fromStorage;
    }
  } catch (_error) {
    // Fall through to the in-memory user id.
  }

  const fromUser = globalAppState?.user?.id;
  return typeof fromUser === 'string' && fromUser.trim().length > 0
    ? fromUser
    : undefined;
};

export const getHealthRecord = async (): Promise<health_info_response> => {
  try {
    const entityId = await resolveMemberEntityId();

    if (!entityId) {
      return {
        success: false,
        data: undefined as unknown as health_info_response['data'],
      };
    }

    const response = await getRequest<any>(
      urls.API_HEALTH_RECORD + '/' + entityId,
      {
        baseURL: Config.BASE_URL_1,
      },
    );
    return Promise.resolve(response.data);
  } catch (error) {
    return handleRequestError(error);
  }
};

