const mockGetRequest = jest.fn();
const mockGetGlobalAppState = jest.fn();
const mockAsyncStorageGetItem = jest.fn();

jest.mock('../src/api/api-client.ts', () => ({
  deleteRequest: jest.fn(),
  getRequest: (...args: unknown[]) => mockGetRequest(...args),
  postRequest: jest.fn(),
  putRequest: jest.fn(),
}));

jest.mock('@react-native-async-storage/async-storage', () => ({
  __esModule: true,
  default: {
    getItem: (key: string): Promise<string | null> =>
      mockAsyncStorageGetItem(key),
    setItem: jest.fn(),
  },
}));

jest.mock('@store/AppContext', () => ({
  getGlobalAppState: () => mockGetGlobalAppState(),
}));

jest.mock('react-native-keychain', () => ({
  setGenericPassword: jest.fn(),
  resetGenericPassword: jest.fn(),
}));

jest.mock('react-native-config', () => ({
  BASE_URL: 'https://api.example.test',
  BASE_URL_1: 'https://api.example.test',
}));

jest.mock('../src/config/index', () => ({
  __esModule: true,
  default: {},
}));

import { getHealthRecord } from '../src/api/api';

describe('getHealthRecord', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockGetRequest.mockResolvedValue({
      data: {
        success: true,
        data: { bloodType: 'O+' },
      },
    });
    mockGetGlobalAppState.mockReturnValue({
      loginData: null,
      user: null,
      setCommonModalKey: jest.fn(),
      setShowErrorModal: jest.fn(),
      setErrorModalText: jest.fn(),
    });
    mockAsyncStorageGetItem.mockResolvedValue(null);
  });

  test('uses the login entity id when it is present', async () => {
    mockGetGlobalAppState.mockReturnValue({
      loginData: { entity: { id: 'entity-from-login' } },
      user: { id: 'user-id' },
    });

    await expect(getHealthRecord()).resolves.toEqual({
      success: true,
      data: { bloodType: 'O+' },
    });

    expect(mockGetRequest).toHaveBeenCalledWith(
      '/v1/health-passport/health-record/entity-from-login',
      { baseURL: 'https://api.example.test' }
    );
    expect(mockAsyncStorageGetItem).not.toHaveBeenCalled();
  });

  test('falls back to cached memberData when login entity id is missing', async () => {
    mockGetGlobalAppState.mockReturnValue({
      loginData: { entity: {} },
      user: { id: 'user-id' },
    });
    mockAsyncStorageGetItem.mockResolvedValue(
      JSON.stringify({ entity: { id: 'entity-from-cache' } })
    );

    await expect(getHealthRecord()).resolves.toEqual({
      success: true,
      data: { bloodType: 'O+' },
    });

    expect(mockAsyncStorageGetItem).toHaveBeenCalledWith('memberData');
    expect(mockGetRequest).toHaveBeenCalledWith(
      '/v1/health-passport/health-record/entity-from-cache',
      { baseURL: 'https://api.example.test' }
    );
  });

  test('does not request /undefined when no member entity id exists', async () => {
    await expect(getHealthRecord()).resolves.toEqual({
      success: false,
      data: undefined,
    });

    expect(mockGetRequest).not.toHaveBeenCalled();
  });
});

